      "steps": [
        "将龙利鱼柳冷藏解冻至柔软，厨房纸吸干水，摸查并拔掉小刺，切成厚不超过2厘米的块。",
        "姜切细丝、葱切小段；把姜铺在浅盘底，鱼块单层放上，不叠高。",
        "蒸锅加入足量水，水面低于蒸架；盖盖，大火把水煮到持续冒蒸汽。",
        "放入鱼盘，盖盖中大火蒸10—12分钟；鱼块厚于2厘米时分小块再蒸，不直接套时间。",
        "掀盖时避开蒸汽；检查最厚处全熟，温度计中心75°C至少30秒，未达标再蒸2分钟复查。",
        "取出鱼盘，加入配方酱油、油与20毫升热水，撒葱；给孩子和长辈分餐时再次拆开找刺。"
      ],
