        "小锅加足以没过西兰花的清水，大火煮沸，先下茎片30秒，再下花朵煮2—3分钟。",
        "捞出沥水；用筷子扎最粗的小茎，能穿过即可，若很硬再煮1分钟。",
        "另取不粘锅，中小火放4克油和蒜末，翻动约20秒至有蒜香，不要炒焦。",
        "放入西兰花，淋2克酱油和20毫升水，中火翻炒1分钟，再加盖焖1分钟。",
        "揭盖翻匀，确认小茎软嫩、花球里外都热透后装盘；给儿童再切小，不另加盐。"
