      "id": "guide-009",
      "name": "海带蛤蜊汤",
      "sourceName": "海带蛤蜊汤",
      "category": "protein",
      "ingredients": [
        {
          "foodId": "guideClamMeatRaw",
          "g": 80
        },
        {
          "foodId": "guideKelpRehydrated",
          "g": 30
        },
        {
          "foodId": "tofu",
          "g": 80
        },
        {
          "foodId": "gingerRaw",
          "g": 3
        },
        {
          "foodId": "oil",
          "g": 3
        },
        {
          "foodId": "salt",
          "g": 0.3
        },
        {
          "foodId": "water",
          "g": 300
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 12,
      "totalMin": 30,
      "steps": [
        "海带／裙带菜按包装泡发洗净、沥水后称量，切1厘米小段；豆腐切1.5厘米小块。",
        "买已去壳蛤蜊肉，冷藏解冻后检查无异味；用流动水快速冲洗并沥干。",
        "小汤锅中火加3克油和姜片，翻动20秒；加入切好的豆腐、蔬菜与配方清水，大火煮沸。",
        "转中火煮5—6分钟，至较硬的蔬菜能用筷子轻穿；海带按包装所需时间先煮软。",
        "放入蛤蜊肉，轻轻拨散，保持小滚约6—8分钟；不要把未熟食材只烫变色就盛出。",
        "检查鱼肉或肉块最厚处中心75°C至少30秒；加入0.3克盐拌匀后关火。汤和固体食材按份一起分，不把喝汤当作吃够肉。"
      ],
      "prep": {
        "mode": "fresh"
      },
      "tags": [
        "新手步骤",
        "家庭健康改写"
      ],
      "estimated": true,
      "defaultEligible": false,
      "fixedMix": true,
      "sizingGroup": "protein",
      "basisNote": "这是依据网上相关烹调方法、为家庭新手重新写的1参考份；食材可食生重／明确标注的熟重，不是个人处方，也不冒称书中原方。时间与盐油克数为应用参考，需要按自家成品校准。",
      "noviceTips": [
        "有食物温度计时，测最厚处中心达75°C并维持至少30秒；没有温度计时，切开检查全熟只能作辅助，拿不准就继续加热。",
        "克数按去骨、去壳、去明显肥油后的可食部分；一次做多人时先按人数相加，锅小就分批煮。",
        "汤菜要把分到的肉、鱼、蛋或豆类吃到，水多不代表蛋白多。",
        "全程时间从鲜料或已解冻原料开始计算，包含洗切；冷冻鱼肉请按包装要求提前冷藏解冻，解冻等待另计。"
      ],
      "healthNotes": [
        "按这里的油盐量操作，不另加鸡精、汤块或浓酱；一顿还需搭配主食和蔬菜。",
        "时间仅作起点；食材厚度、火力和锅具不同，要以熟透判断为准。",
        "尿酸关注者不默认安排此海鲜或肉汤选项，按个人尿酸与已有方案选菜；不喝浓缩肉汤来补营养。"
      ],
