      "id": "guide-018",
      "name": "清炒红菜头（甜菜根丝）",
      "category": "veg",
      "ingredients": [
        {
          "foodId": "beetrootRaw",
          "g": 200
        },
        {
          "foodId": "garlicRaw",
          "g": 3
        },
        {
          "foodId": "oil",
          "g": 4
        },
        {
          "foodId": "salt",
          "g": 0.3
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 15,
      "totalMin": 22,
      "steps": [
        "确认买的是红菜头/甜菜根块根，不是红苋菜；刷洗泥土后削皮，切成约2毫米细丝，蒜切末。",
        "不粘锅中火预热30秒，倒入4克油，蒜末小火炒15秒，闻香即可。",
        "倒入甜菜根丝，中火翻炒2分钟，让细丝均匀沾上油。",
        "加60毫升水，盖上锅盖，转中小火焖6分钟；中途开盖翻动一次，锅干则每次补1汤匙水。",
        "揭盖，加0.3克盐拌炒1分钟；夹起最粗的菜丝，应能被筷子轻压断、没有硬生脆芯，不够软再焖2分钟。",
        "盛盘，给孩子和老人剪成短丝，温热食用；红色菜汁染到砧板及时洗净。"
      ],
