      "steps": [
        "选正规售卖的栽培口蘑，洗净后切成约4毫米片；菠菜去根洗净，切3厘米段，蒜切末，生熟工具分开。",
        "烧开一锅水，菠菜先放茎30秒，再放叶煮1分钟；捞出沥干，焯水倒掉。",
        "不粘锅中火入4克油，放口蘑片，翻炒2分钟，表面开始出水。",
        "加蒜末和20毫升水，转中小火盖上焖4分钟，中途翻一次，让所有菇片都受热。",
        "揭盖，菇片应明显缩小软嫩，没有生硬感；加入菠菜与0.3克盐，中火翻炒1分钟。",
        "确认菠菜重新热透、蘑菇全熟后盛盘，给孩子和老人把菇片再剪小，趁热吃。"
      ],
