      "steps": [
        "选不辣的甜椒，红、黄椒均可；整只洗净后切开，去蒂、籽和白色硬筋，再称200克。",
        "将甜椒切成约2厘米方片，蒜切薄片；给孩子吃的椒片可切成1厘米宽短条。",
        "不粘锅中火热30秒，入4克油，蒜片小火炒15秒，稍有香味即可。",
        "加甜椒，中火翻炒2分钟，再加20毫升水，盖锅焖2分钟。",
        "揭盖，加0.3克盐再翻炒30秒；椒片应能弯折、咬开无硬生感，老人需要更软可再焖1—2分钟。",
        "盛到干净盘中，温热食用；不把辣椒当作本配方甜椒替换给孩子。"
      ],
