      "steps": [
        "紫薯先流水刷净，削皮去损伤处，称可食部150g，切成约3厘米块；这份量按生可食部计。",
        "蒸锅加水至低于蒸架，放空蒸架后盖盖，大火烧至持续冒汽。",
        "紫薯放耐热盘并铺成单层，放进蒸锅，盖盖后以中大火蒸20～25分钟；注意锅中留有足水。",
        "用筷子插最厚一块，能轻松穿透、内部松软无硬芯再关火；未熟每次加蒸5分钟。",
        "用隔热手套取盘，晾到不烫口，可切小或压泥；不额外撒糖。"
      ],
      "noviceTips": [
        "紫薯不是紫山药，购买时确认食材。",
        "份量为菜谱计算参考，按实际选中的就餐人调整，不要求每个人吃一样多。"
      ],
      "healthNotes": [
        "紫薯是主食选择，食用量仍需结合其他主食。"
      ],
      "guideVersion": "novice-1",
