      "id": "guide-038",
      "name": "紫甘蓝沙拉（焯熟温拌版）",
      "category": "veg",
      "ingredients": [
        {
          "foodId": "purpleCabbageRaw",
          "g": 150
        },
        {
          "foodId": "carrot",
          "g": 50
        },
        {
          "foodId": "oliveOil",
          "g": 3
        },
        {
          "foodId": "vinegar",
          "g": 5
        },
        {
          "foodId": "salt",
          "g": 0.2
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 12,
      "totalMin": 16,
      "steps": [
        "紫甘蓝去最外层老叶和中间硬芯，逐片冲洗后切成2毫米细丝；胡萝卜洗净削皮，切2毫米细丝。",
        "烧开一锅清水，下胡萝卜丝，煮2分钟。",
        "加入紫甘蓝丝，水再沸后煮2—3分钟，夹起一根能轻松咬断即可，咀嚼弱者再多煮1分钟。",
        "将两种菜捞入干净漏勺沥水，不用生水过凉，倒入干净大碗。",
        "混合3克橄榄油、5克醋和0.2克盐，搅匀后淋入菜中，翻拌20秒。",
        "稍降至入口温度即食；给儿童老人将长丝剪短，不加整粒坚果或厚重沙拉酱。"
      ],
      "prep": {
        "mode": "fresh"
      },
