      "fixedMix": true,
      "sizingGroup": "veg",
      "basisNote": "应用1参考份，原料为去掉不可食部分后的生重（海带与魔芋丝按注明状态）；并非个人处方或该书原方。克数、时间和少油少盐调味均为家庭健康改写，熟重待实测。",
      "noviceTips": [
        "先煮软后拌，别只在热水中涮一下就捞；本份不再加盐。",
        "想留下一餐，先用干净餐具单独分装到浅盒，快速降温后2小时内放入4℃以下冰箱；食用时彻底热透，只加热一次。",
        "份量为菜谱计算参考，按实际选中的就餐人调整，不要求每个人吃一样多。"
      ],
