      "id": "guide-040",
      "name": "香煎三文鱼",
      "sourceName": "香煎三文鱼",
      "category": "protein",
      "ingredients": [
        {
          "foodId": "salmon",
          "g": 120
        },
        {
          "foodId": "oil",
          "g": 3
        },
        {
          "foodId": "salt",
          "g": 0.3
        },
        {
          "foodId": "blackPepper",
          "g": 0.1
        },
        {
          "foodId": "gingerRaw",
          "g": 3
        },
        {
          "foodId": "water",
          "g": 30
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 12,
      "totalMin": 25,
      "steps": [
        "将三文鱼冷藏解冻至柔软，厨房纸吸干水，摸查并拔掉小刺，切成厚不超过2厘米的块。",
        "把鱼两面抹匀配方盐与胡椒，静置3分钟；不再加酱油或黄油。",
        "用不粘平底锅，中火预热约30秒，倒入3克油转开，放姜片。",
        "鱼块平放入锅，有皮的一面先向下；中小火煎3分钟，先不来回挪动。",
        "用锅铲轻翻面，再煎3分钟；沿锅边加30毫升水，盖盖小火焖2—3分钟。",
        "测最厚处中心75°C至少30秒；未熟继续小火加热。鱼肉应全不透明，盛出后再仔细挑刺。"
      ],
      "prep": {
        "mode": "fresh"
      },
      "tags": [
        "新手步骤",
        "家庭健康改写"
      ],
      "estimated": true,
      "defaultEligible": false,
      "fixedMix": true,
      "sizingGroup": "protein",
      "basisNote": "这是依据网上相关烹调方法、为家庭新手重新写的1参考份；食材可食生重／明确标注的熟重，不是个人处方，也不冒称书中原方。时间与盐油克数为应用参考，需要按自家成品校准。",
      "noviceTips": [
        "有食物温度计时，测最厚处中心达75°C并维持至少30秒；没有温度计时，切开检查全熟只能作辅助，拿不准就继续加热。",
        "克数按去骨、去壳、去明显肥油后的可食部分；一次做多人时先按人数相加，锅小就分批煮。",
        "全程时间从鲜料或已解冻原料开始计算，包含洗切；冷冻鱼肉请按包装要求提前冷藏解冻，解冻等待另计。"
      ],
      "healthNotes": [
        "按这里的油盐量操作，不另加鸡精、汤块或浓酱；一顿还需搭配主食和蔬菜。",
        "时间仅作起点；食材厚度、火力和锅具不同，要以熟透判断为准。",
        "鱼肉分餐前再次去刺；哺乳者和儿童需按真实鱼种选低汞鱼，不能单凭“鳕鱼”等商品名判断。"
      ],
