      "id": "guide-041",
      "name": "凉拌豆苗（全熟温拌版）",
      "category": "veg",
      "ingredients": [
        {
          "foodId": "peaShootsRaw",
          "g": 200
        },
        {
          "foodId": "garlicRaw",
          "g": 3
        },
        {
          "foodId": "oil",
          "g": 3
        },
        {
          "foodId": "soySauce",
          "g": 2
        },
        {
          "foodId": "vinegar",
          "g": 4
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 12,
      "totalMin": 16,
      "steps": [
        "选正规渠道的食用豌豆苗，不用来历不明芽菜；摘掉粗老茎和卷须，逐把在流动水下洗净，切成3厘米段。",
        "蒜切细末；准备干净漏勺和熟食盘，避免煮好后接触装过生菜的容器。",
        "一锅清水大火烧沸，先放较粗豆苗茎30秒，再把叶放入并翻散。",
        "水重新沸腾后继续煮2—3分钟，直到全部茎叶软下、最粗的茎也无生硬感；不能仅浇开水。",
        "捞出沥水，不冲生水；小碗混合3克油、2克酱油和4克醋，拌入熟豆苗和蒜末。",
        "用干净筷子拌匀，温热食用，给孩子和老人剪成短段；若仍觉茎硬，回锅加水再煮1分钟。"
      ],
