      "steps": [
        "番茄整只用流动清水搓洗，去蒂硬芯，选择成熟无破损的果实。",
        "给孩子或咀嚼弱者，可在表面浅划十字，沸水烫约30秒后放至不烫手，剥去外皮。",
        "番茄切成约2厘米块；将3克油、0.2克盐、50毫升水备好。",
        "小锅放油，中小火下番茄，轻翻约1分钟，不把锅烧到冒烟。",
        "倒入50毫升水，加盖小火煮4—5分钟；中途翻一次，煮到每块都热透、能用勺压碎。",
        "加入0.2克盐搅匀，盛碗温热食用；孩子吃大块不方便时压成带颗粒的番茄泥。"
      ],
