      "steps": [
        "称干藜麦35g、大米25g，共60g干粮；用细筛冲洗藜麦，大米轻淘后沥水，放电饭煲并加90g新水，约为干粮:水1:1.5的试做起点。",
        "选适合机型的煮饭程序，约35～45分钟，完成后焖10分钟再翻松；颗粒应无硬心，米种及机型不同按说明书调整。小量低于最低煮饭量时做成倍批量。",
        "煮饭时烤箱预热200℃。西兰花切小朵洗净；三文鱼用厨房纸吸干，逐一摸查并夹掉鱼刺，生鱼与蔬菜分开操作。",
        "烤盘上放鱼和西兰花，合计拌或刷3g油、撒0.4g盐；加1～2勺水避免蔬菜发干，放中层烤约15～20分钟。",
        "最厚鱼肉应中心熟透，温度达75℃并维持30秒；没温度计时切开确认完全不透明且能分成片，无半透明生心，不能只看表面变色。",
        "藜麦饭盛碗，放入鱼与熟西兰花；给孩子再查鱼刺并把鱼肉拆碎，蔬菜需软熟。"
      ],
      "noviceTips": [
        "本碗同时有主食、鱼和蔬菜；不把藜麦少量点缀视为足够主食。",
        "全程时间从鲜料或已解冻原料开始计算，包含洗切；冷冻鱼肉请按包装要求提前冷藏解冻，解冻等待另计。"
      ],
      "healthNotes": [
        "含鱼。尿酸关注者需按实际疾病状态与医生建议决定鱼量，不声称三文鱼或藜麦能降尿酸。"
      ],
