        "牛肉分散放入，不在一处堆成团；中火煮约3分钟，检查牛肉最厚处中心75°C至少30秒。",
        "加0.3克盐即关火，按配方分食固体；尿酸关注者不默认安排此肉汤，不靠大量喝汤补蛋白。"
