        "加入芦笋和30毫升水，加盖转中小火焖4分钟，中途开盖翻一次。",
        "揭盖，淋2克酱油，中火翻炒30秒；确认口蘑软嫩全熟、芦笋粗段能被筷子扎透。",
        "仍硬则加1汤匙水再焖1—2分钟；达标后盛盘，孩子老人吃前将长段剪短。"
