      "basisNote": "原书为1人份，保留希腊酸奶200g；应用将莓果定为总重80g、即食混合种子定为10g，不把原书蓝莓与树莓各8～10颗、种子1包伪换算成克数。应用1参考份，并非个人处方或原书原方。",
