        "取新鲜蓝莓、树莓合计80g，去掉坏果，流水轻洗后沥干；本重量是应用示例，并非把书中各8～10颗精确换算。",
        "称包装明确可直接食用的混合种子10g；这是应用份量，并非把书中“1包”精确换算。若包装要求加热，先照包装处理并冷却。",
        "混合种子中大颗粒的南瓜籽等先磨细；如果包含奇亚籽，把其与一小部分酸奶拌匀冷藏浸润15分钟，实际总时间相应延长。",
        "将莓果和处理好的种子拌入酸奶，大颗蓝莓给孩子切小，拌好尽快吃；不用蜂蜜或蛋白粉增加甜度或稠度。"
