      "steps": [
        "藜麦40克用细筛冲洗，放小锅加90毫升水；煮沸后盖盖小火15分钟，再关火焖5分钟。",
        "生菜逐片洗净，番茄切块；另烧半锅沸水，叶菜烫30—60秒至软、捞出沥干。熟蔬菜和生牛肉分开用刀板及夹子。",
        "牛肉逆纹切成约0.5厘米薄片，撒配方盐与胡椒，静置3分钟；洗净双手和生肉用具。",
        "不粘平底锅中火放4克油，牛肉摊平煎2分钟，翻面再煎2分钟；加20毫升水盖盖焖1—2分钟。",
        "确认牛肉最厚处中心75°C至少30秒；关火，用干净夹子放到熟食盘，切小段。",
        "熟藜麦、熟蔬菜和熟牛肉装碗，拌入5克醋；给长辈和孩子切成适口小块，现做现吃。"
      ],
