        "深平底锅加3g油，中火放牛肉末，用锅铲压散炒3～4分钟，直到全部变色不成团；生肉用具不要直接夹熟食。",
        "加入洋葱、胡萝卜与蒜末炒2～3分钟，倒番茄、10g番茄膏和100g水，搅匀煮开。",
        "转小火半盖炖20～25分钟，中间搅拌防黏底；酱太干加少量热水，确保肉末熟透，中心达75℃并维持30秒。",
        "炖酱最后10～12分钟另烧一锅足水，放60g干全麦意面，按包装煮到无硬心；儿童可煮得更软。",
        "沥面后倒入酱锅，加入0.4g盐拌匀，再小火煮1分钟；盛盘放至适口温度，不额外撒高盐肉酱或芝士粉。"
