      "activeMin": 10,
      "totalMin": 30,
      "steps": [
        "烤箱预热至220℃上下火；西兰花洗净切约2—3厘米小朵，粗茎削皮切3毫米片。",
        "用厨房纸把花球表面轻轻吸干，放大碗，加4克油、0.3克盐和少量黑胡椒，拌约30秒。",
        "铺在烤盘烘焙纸上，摊成单层，花朵间留空隙；不堆成厚厚一团。",
        "送入中层烤约10分钟，戴隔热手套取出，用夹子翻面再放回烤8—10分钟。",
        "用筷子扎最粗的茎，应能轻松穿透，花尖只是少量金黄、不焦黑；茎硬时盖一张锡纸再烤3—5分钟。",
        "取出稍凉到适口温度再吃；给孩子和老人剪成小朵，硬焦部分不提供。"
      ],
