      "id": "guide-079",
      "name": "清蒸三文鱼",
      "sourceName": "清蒸三文鱼",
      "category": "protein",
      "ingredients": [
        {
          "foodId": "salmon",
          "g": 120
        },
        {
          "foodId": "gingerRaw",
          "g": 3
        },
        {
          "foodId": "scallionRaw",
          "g": 3
        },
        {
          "foodId": "soySauce",
          "g": 2
        },
        {
          "foodId": "oil",
          "g": 3
        },
        {
          "foodId": "water",
          "g": 20
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 10,
      "totalMin": 25,
      "steps": [
        "将三文鱼冷藏解冻至柔软，厨房纸吸干水，摸查并拔掉小刺，切成厚不超过2厘米的块。",
        "姜切细丝、葱切小段；把姜铺在浅盘底，鱼块单层放上，不叠高。",
        "蒸锅加入足量水，水面低于蒸架；盖盖，大火把水煮到持续冒蒸汽。",
        "放入鱼盘，盖盖中大火蒸10—12分钟；鱼块厚于2厘米时分小块再蒸，不直接套时间。",
        "掀盖时避开蒸汽；检查最厚处全熟，温度计中心75°C至少30秒，未达标再蒸2分钟复查。",
        "取出鱼盘，加入配方酱油、油与20毫升热水，撒葱；给孩子和长辈分餐时再次拆开找刺。"
      ],
      "prep": {
        "mode": "fresh"
      },
      "tags": [
        "新手步骤",
        "家庭健康改写"
      ],
      "estimated": true,
      "defaultEligible": false,
      "fixedMix": true,
      "sizingGroup": "protein",
      "basisNote": "这是依据网上相关烹调方法、为家庭新手重新写的1参考份；食材可食生重／明确标注的熟重，不是个人处方，也不冒称书中原方。时间与盐油克数为应用参考，需要按自家成品校准。",
      "noviceTips": [
        "有食物温度计时，测最厚处中心达75°C并维持至少30秒；没有温度计时，切开检查全熟只能作辅助，拿不准就继续加热。",
        "克数按去骨、去壳、去明显肥油后的可食部分；一次做多人时先按人数相加，锅小就分批煮。",
        "全程时间从鲜料或已解冻原料开始计算，包含洗切；冷冻鱼肉请按包装要求提前冷藏解冻，解冻等待另计。"
      ],
      "healthNotes": [
        "按这里的油盐量操作，不另加鸡精、汤块或浓酱；一顿还需搭配主食和蔬菜。",
        "时间仅作起点；食材厚度、火力和锅具不同，要以熟透判断为准。",
        "鱼肉分餐前再次去刺；哺乳者和儿童需按真实鱼种选低汞鱼，不能单凭“鳕鱼”等商品名判断。"
      ],
