      "id": "guide-082",
      "name": "蒜香口蘑（替代炒牛肝菌）",
      "category": "veg",
      "ingredients": [
        {
          "foodId": "mushroom",
          "g": 200
        },
        {
          "foodId": "garlicRaw",
          "g": 4
        },
        {
          "foodId": "oil",
          "g": 4
        },
        {
          "foodId": "soySauce",
          "g": 2
        }
      ],
      "portions": 1,
      "cookedG": null,
      "activeMin": 12,
      "totalMin": 18,
      "steps": [
        "这道明确改用正规超市栽培口蘑，不购野生牛肝菌；洗去表面泥屑，切掉硬蒂底，切成约4毫米片。",
        "蒜去皮切片，把4克油和2克酱油称好，另备30毫升水。",
        "不粘锅中火预热30秒，放油和口蘑，翻炒2分钟，让菇片开始出水。",
        "放蒜片和30毫升水，转中小火加盖焖5分钟，中途翻动一次，避免一部分菇片未受热。",
        "揭盖中火翻炒1—2分钟，淋酱油拌匀；菇片应完全软嫩、颜色均匀、没有生硬中心。",
        "装盘温热食用；给孩子与老人切成更小片，这套时间只用于本配方口蘑，不能套用牛肝菌。"
      ],
      "prep": {
        "mode": "fresh"
      },
