      "sizingGroup": "grain",
      "activeMin": 15,
      "totalMin": 35,
      "steps": [
        "本条做一碗家常虾仁蔬菜藜麦组合，不推断书页连写菜名的拆分。先用细筛洗净干藜麦55g，沥水后与155g新水放带盖奶锅。",
        "大火烧开后转小火盖盖煮12～15分钟，至水基本收干、藜麦无硬心，再关火焖10分钟；太干却仍硬时补少量热水。",
        "西兰花洗净切小朵，胡萝卜切薄片，番茄洗净切小块；虾仁另在生食区检查虾线，用厨房纸吸去水分。",
        "另一锅水烧沸，先煮胡萝卜2分钟，再加西兰花煮约3分钟至软熟，用干净漏勺捞起沥水。",
        "原锅保持沸腾，加入虾仁煮约2～4分钟，随虾大小调整；最厚处应白透无透明生心，中心达75℃并维持30秒，之后用另一把干净漏勺捞出。",
        "藜麦拨松后放碗，拌入熟虾和熟蔬菜、番茄、油4g、醋5g与盐0.4g；保留温热立即吃，给孩子将虾切小。",
        "如果想吃冷沙拉，熟料迅速摊浅降温后立即冷藏，生蔬菜与熟海鲜工具分开；不把煮好的海鲜整锅室温放到下一餐。"
      ],
      "noviceTips": [
        "主食明确为55g干藜麦，蛋白质主要来自80g生去壳虾仁，均不是熟重。",
        "全程时间从鲜料或已解冻原料开始计算，包含洗切；冷冻鱼肉请按包装要求提前冷藏解冻，解冻等待另计。"
      ],
      "healthNotes": [
        "含甲壳类。尿酸关注者按自身病情决定海鲜摄入，不以“沙拉”代表适合所有人。"
      ],
