        "小汤锅中火倒入3克油和姜片，拌20秒；倒入300毫升水，大火煮沸。",
        "放入准备好的蔬菜，中火煮4—5分钟。",
        "把火调至汤持续小滚，沿锅边细细倒入蛋液，等20秒再轻推两圈。",
        "继续煮1—2分钟至蛋花完全凝固、汤滚烫；加入0.3克盐，中心75°C至少30秒后关火盛出。"
