      "steps": [
        "选择无额外加糖的干红枣，剔掉霉变果；流水搓洗表面并沥水，准备小刀、耐热小碗和蒸锅。",
        "沿枣身纵向切开，用手掰开并完全取出枣核，逐个检查核尖和碎核；称去核可食部15g。",
        "将红枣切小片放碗里，另加1～2勺饮用水防干；蒸锅加水，大火烧到持续出汽再放碗。",
        "盖盖中火蒸15～20分钟，直到枣肉能用勺压碎；如果仍偏硬，补少量热水后续蒸5分钟。",
        "稍凉后再检查没有碎核；给孩子和咀嚼困难老人可去掉难嚼的皮、压成泥，随餐吃，不额外加糖。"
      ],
