      "steps": [
        "虾仁在冷藏室解冻，去壳、尾壳和虾线；快速冲洗沥水，较大只从背部浅切开。",
        "姜切细丝铺浅盘底，虾仁摊成一层，不堆成厚团。",
        "配方油、酱油和20毫升清水拌匀，均匀淋在虾仁上。",
        "蒸锅水大火煮沸，放虾盘，盖盖中大火蒸6—8分钟。",
        "夹开最大一只检查：虾肉全部不透明且结实；中心75°C至少30秒，未达标再蒸2分钟复查。",
        "关火取出，撒葱，给孩子切成小段再分餐；不让生虾碗筷接触熟虾。"
      ],
