      "steps": [
        "牛腩剪去明显白色肥油，切约2厘米块；番茄切块，洋葱切丁，胡萝卜切1厘米块。",
        "牛腩放小锅加冷水没过，大火煮开后再煮2分钟；捞出沥水，弃掉这锅焯水。",
        "厚底炖锅中火放3克油，炒洋葱1分钟；加番茄与10克无添加糖番茄膏，翻炒2分钟。",
        "放牛腩、胡萝卜、姜及配方450毫升热水，大火煮开后改小火，盖盖让汤轻轻冒小泡。",
        "小火炖70—90分钟，每20分钟查看，水快干时少量添热水；直到筷子能轻松插入牛肉，不能只凭计时停火。",
        "确认牛肉中心75°C至少30秒，加入0.3克盐拌匀；冷却后撇去表面浮油，按1餐量分装，吃肉和蔬菜、不过量喝浓汤。"
      ],
