        "鱼柳冷藏解冻后摸查去刺，切约1厘米小丁；有虾时去虾线、尾壳并切小丁。",
        "鱼／虾丁放沸水中中火煮3—4分钟，捞出；这一步只作预熟，后面仍要蒸透。",
        "鸡蛋在干净碗中打散，加入100毫升温而不烫手的水、0.3克盐拌匀；豆腐切小丁。",
        "耐热浅碗抹3克油，放豆腐、鱼／虾及姜末，倒入蛋液；液面深度尽量不超过4厘米。",
        "蒸锅水煮沸后放碗，扣一个耐热小盘作盖，中火蒸15—18分钟。",
        "轻晃碗，蛋羹应整体凝固；用温度计测中心75°C至少30秒，未达标再蒸2分钟复查。"
