        "鸡胸肉沿厚度方向横切成约1—1.5厘米厚片；不在水龙头下冲洗生鸡肉，处理后清洁台面和手。",
        "鸡肉拌3克酱油、胡椒和10毫升配方水，放冰箱冷藏腌10分钟；蒜切薄片。",
        "不粘平底锅中火预热30秒，放4克油和蒜片炒15秒；鸡肉铺成一层煎3分钟。",
        "翻面再煎3分钟，加余下30毫升水，盖盖小火焖5—6分钟。",
        "温度计插最厚部分中心，确认75°C至少30秒；未达标再焖2分钟复查，不靠外面金黄判断。",
        "关火用干净刀切成方便入口的小块，另配蔬菜和主食；不把腌生鸡的汁当蘸汁。"
