        "锅中加油，中火加热至油易流动但不冒烟，下蒜末炒约10秒，不要炒黑。",
        "放香菇片，中大火翻炒约2分钟；变软后加入青菜梗炒约1分钟，锅太干时沿锅边加入备好的水。",
        "加入青菜叶，翻炒约1—2分钟至叶片塌软；转中火加盖约1分钟，让香菇和菜梗都熟透，锅干则补少量水，不能只看叶子颜色判断。",
        "开盖加盐翻匀约20秒；检查最厚的菜梗能轻松咬断、香菇全熟后立即盛盘。给孩子和老人时按咀嚼能力剪短，趁热吃。"
