      "nutritionComment": [
        "青菜和鲜香菇可帮助增加蔬菜种类及膳食纤维来源；鲜香菇营养值未核验，不宣称精确纤维或钙含量。",
        "不能把这盘菜当作治疗三高、降尿酸或单独补足哺乳期营养的手段。"
      ],
      "uricAcidNote": "2024食养指南所列鲜香菇与干制菌菇不是同重量同状态的食品；一般无需仅因名字含香菇就自动禁掉这道鲜菇蔬菜，仍按个人临床方案及诱发史调整。",
