      "label": "中国居民膳食指南（2022）核心推荐（福建省卫健委，来源中国疾控中心）",
      "url": "https://wjw.fujian.gov.cn/ztzl/jkjy/jkzgxd/202206/t20220615_5930367.htm",
      "note": "普通成人鱼2次或300—500克/周、畜禽肉300—500克/周，蔬菜至少300克/日，盐≤5克/日、油25—30克/日；不直接套成儿童、哺乳期或患病老人处方。"
